// Writes tests/fixtures/messages.golden.ts: every message in hooks/messages.ts, rendered from its example. Run after
// reviewing a wording change (npm run golden); the diff of the golden file is the review of every sentence that changed.
import { writeFileSync } from 'node:fs'

import { renderAll } from '../hooks/messages.ts'

const lines = Object.entries(renderAll()).map(([id, text]) => `  ${JSON.stringify(id)}: ${JSON.stringify(text)},`)
const file = [
  '// Generated by `npm run golden` from hooks/messages.ts. Do not edit by hand: change the template, then regenerate,',
  '// and review this diff: it is every sentence the agent will read differently.',
  'export const GOLDEN: Record<string, string> = {',
  ...lines,
  '}',
  '',
].join('\n')
writeFileSync(new URL('../tests/fixtures/messages.golden.ts', import.meta.url), file)
console.log(`golden: ${lines.length} messages written to tests/fixtures/messages.golden.ts`)
